// src/routes/checkout.tsx
import { useState } from 'react';
import { useNavigate } from 'react-router-dom';

export default function Checkout() {
  const [submitting, setSubmitting] = useState(false);
  const [orderId, setOrderId] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const navigate = useNavigate();

  async function onSubmit(e: React.FormEvent<HTMLFormElement>) {
    e.preventDefault();
    setSubmitting(true);
    const form = new FormData(e.currentTarget);
    const res = await fetch('/api/orders', {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({
        cardLast4: String(form.get('cardLast4') ?? ''),
        email: String(form.get('email') ?? ''),
      }),
    });
    setSubmitting(false);
    if (!res.ok) {
      setError('Payment failed. Your card was not charged.');
      return;
    }
    const body = (await res.json()) as { id: string };
    setOrderId(body.id);
    navigate(`/orders/${body.id}`);
  }

  return (
    <main>
      <h1>Checkout</h1>
      {submitting && <p role="status">Placing your order...</p>}
      {error && <p role="alert">{error}</p>}
      {orderId && <p role="status">Order {orderId} confirmed</p>}
      <form onSubmit={onSubmit} aria-label="Checkout">
        <label htmlFor="email">Email</label>
        <input id="email" name="email" type="email" required />
        <label htmlFor="cardLast4">Card last 4</label>
        <input id="cardLast4" name="cardLast4" required />
        <button type="submit" disabled={submitting}>Place order</button>
      </form>
    </main>
  );
}

// server/routes/orders.ts
import type { Request, Response } from 'express';
import { createOrder } from '../services/orders.service';

export async function postOrder(req: Request, res: Response) {
  const { email, cardLast4 } = req.body ?? {};
  if (!email || !cardLast4) {
    return res.status(400).json({ error: 'email and cardLast4 are required' });
  }
  const order = await createOrder({ email, cardLast4 });
  return res.status(201).json({ id: order.id, status: order.status });
}

