// src/api/client.ts
// NOTE: this is a SOURCE MODULE served by the Vite dev server, not an HTTP endpoint.
// Its URL under the dev server contains '/api/' — a `**/api/**` fulfilling route
// pattern intercepts it and hands the browser a JSON mock instead of JavaScript,
// so the app fails to boot in a way that looks like a product bug.
export interface Project {
  id: string;
  name: string;
}

const BASE = import.meta.env.VITE_API_BASE ?? 'http://127.0.0.1:8787';

export async function listProjects(): Promise<Project[]> {
  const res = await fetch(`${BASE}/api/projects`, { headers: { accept: 'application/json' } });
  if (!res.ok) throw new Error(`listProjects failed: ${res.status}`);
  return (await res.json()) as Project[];
}

export async function createProject(name: string): Promise<Project> {
  const res = await fetch(`${BASE}/api/projects`, {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ name }),
  });
  if (!res.ok) throw new Error(`createProject failed: ${res.status}`);
  return (await res.json()) as Project;
}

export function reportTelemetry(event: string): void {
  void fetch('https://telemetry.example.net/v1/collect', {
    method: 'POST',
    body: JSON.stringify({ event }),
  });
}

// src/routes/projects.tsx
import { useEffect, useState } from 'react';
import { createProject, listProjects, reportTelemetry, type Project } from '../api/client';

export default function Projects() {
  const [projects, setProjects] = useState<Project[]>([]);
  const [name, setName] = useState('');

  useEffect(() => {
    void listProjects().then(setProjects);
  }, []);

  async function onCreate(e: React.FormEvent) {
    e.preventDefault();
    const created = await createProject(name);
    setProjects((p) => [...p, created]);
    reportTelemetry('project_created');
    setName('');
  }

  return (
    <main>
      <h1>Projects</h1>
      <form onSubmit={onCreate} aria-label="Create project">
        <label htmlFor="name">Project name</label>
        <input id="name" value={name} onInput={(e) => setName((e.target as HTMLInputElement).value)} />
        <button type="submit">Create project</button>
      </form>
      <ul>
        {projects.map((p) => (
          <li key={p.id}>{p.name}</li>
        ))}
      </ul>
    </main>
  );
}

// server/routes/projects.ts
import type { Request, Response } from 'express';

const projects: { id: string; name: string }[] = [];

export function getProjects(_req: Request, res: Response) {
  return res.json(projects);
}

export function postProject(req: Request, res: Response) {
  const name = String(req.body?.name ?? '').trim();
  if (!name) return res.status(400).json({ error: 'name is required' });
  const project = { id: `p_${projects.length + 1}`, name };
  projects.push(project);
  return res.status(201).json(project);
}

