// src/components/OrdersPanel.tsx
import { useEffect, useState } from 'react';
import { fetchOrders, type Order } from '../api/orders';

// The spinner is rendered on mount, BEFORE the request resolves — it is visible
// within milliseconds and stays visible until the request settles. A spec that
// asserts on the spinner passes whether the request succeeds, fails with 500, or
// never completes at all: it proves nothing about the error path.
export function OrdersPanel() {
  const [orders, setOrders] = useState<Order[] | null>(null);
  const [failed, setFailed] = useState(false);

  useEffect(() => {
    let cancelled = false;
    fetchOrders()
      .then((o) => {
        if (!cancelled) setOrders(o);
      })
      .catch(() => {
        if (!cancelled) setFailed(true);
      });
    return () => {
      cancelled = true;
    };
  }, []);

  if (failed) {
    return (
      <div role="alert">
        <h2>We could not load your orders</h2>
        <p>Something went wrong on our end. Please retry in a moment.</p>
        <button type="button" onClick={() => location.reload()}>Retry</button>
      </div>
    );
  }

  if (orders === null) {
    return <p role="status">Loading your orders...</p>;
  }

  return (
    <ul aria-label="Orders">
      {orders.map((o) => (
        <li key={o.id}>{o.reference}</li>
      ))}
    </ul>
  );
}

