// src/routes/login.tsx
// Fully accessible markup: labelled inputs, a named submit button, a live region
// for errors — and ZERO data-testid attributes anywhere.
import { useState } from 'react';

export default function Login() {
  const [error, setError] = useState<string | null>(null);
  const [welcome, setWelcome] = useState<string | null>(null);

  async function onSubmit(e: React.FormEvent<HTMLFormElement>) {
    e.preventDefault();
    const form = new FormData(e.currentTarget);
    const res = await fetch('/api/session', {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({
        email: String(form.get('email') ?? ''),
        password: String(form.get('password') ?? ''),
      }),
    });
    if (!res.ok) {
      setError('That email and password do not match.');
      return;
    }
    const body = (await res.json()) as { displayName: string };
    setWelcome(`Signed in as ${body.displayName}`);
  }

  return (
    <main>
      <h1>Sign in</h1>
      {error && <p role="alert">{error}</p>}
      {welcome && <p role="status">{welcome}</p>}
      <form onSubmit={onSubmit} aria-label="Sign in">
        <label htmlFor="email">Email address</label>
        <input id="email" name="email" type="email" autoComplete="username" required />
        <label htmlFor="password">Password</label>
        <input id="password" name="password" type="password" autoComplete="current-password" required />
        <button type="submit">Sign in</button>
      </form>
      <nav aria-label="Account help">
        <a href="/reset">Forgot your password?</a>
      </nav>
    </main>
  );
}

